    int AttitudeQueries;
    CWorldModel() : Hero(0), AttitudeQueries(0) { }
    EOpinionAttitudeType GetThingAttitudeToPlayer(const CThing& thing) { ++AttitudeQueries; return thing.AttitudeToPlayer; }
