        shopThing.Def = plainDef; heroStats.TradeSkill = 0.5f;
        int queries = world.AttitudeQueries;
        if (shop.GetAttitudeBuyPriceMultiplier() != 1.0f || world.AttitudeQueries != queries) ok = false;
